if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['delete_id'])){verify_csrf();$id=(int)$_POST['delete_id'];$q=db()->prepare('SELECT name,code FROM customers WHERE id=?');$q->execute([$id]);$old=$q->fetch()?:[];$s=db()->prepare('DELETE FROM customers WHERE id=?');$s->execute([$id]);audit_log('customer_deleted','customer',$id,$old);flash('success','Customer and their shipments deleted.');redirect('customers.php');}
$q=trim($_GET['q']??'');$s=db()->prepare('SELECT c.*,COUNT(s.id) shipment_count FROM customers c LEFT JOIN shipments s ON s.customer_id=c.id WHERE c.name LIKE ? OR c.code LIKE ? GROUP BY c.id ORDER BY c.created_at DESC');$like='%'.$q.'%';$s->execute([$like,$like]);$rows=$s->fetchAll();?>
<div class="d-flex flex-wrap gap-2 justify-content-between mb-4"><h1 class="h3">Customers</h1><div><a class="btn btn-outline-success" href="export-customers.php">Export CSV</a> <a class="btn btn-primary" href="customer-add.php">+ Add Customer</a></div></div><form class="card p-3 mb-3"><div class="input-group"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Search by name or customer code"><button class="btn btn-outline-primary">Search</button></div></form><div class="card table-card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Customer Name</th><th>Code</th><th>Phone</th><th>Shipments</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="fw-semibold"><?=e($r['name'])?></td><td><?=e($r['code'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['shipment_count'])?></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="customer-view.php?id=<?=$r['id']?>">View</a> <a class="btn btn-sm btn-outline-secondary" href="customer-edit.php?id=<?=$r['id']?>">Edit</a> <a class="btn btn-sm btn-outline-info" target="_blank" href="../onlineview.php?code=<?=urlencode($r['code'])?>">Tracking</a> <form method="post" class="d-inline" onsubmit="return confirm('Delete this customer and every shipment belonging to them?')"><?=csrf_field()?><input type="hidden" name="delete_id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="text-center text-muted py-4">No customers found.</td></tr><?php endif;?></tbody></table></div></div>
